"""FactuAPI — service de facturation (routes publiques et protégées)."""

from . import store


def health(request):
    return {"status": 200, "body": {"status": "ok"}}


def login(request):
    token = request.get("json", {}).get("token", "")
    try:
        return {"status": 200, "body": {"user": store.user_from_token(token)}}
    except PermissionError:
        return {"status": 401, "body": {"error": "jeton invalide"}}


def list_invoices(request):
    user = request["user"]
    if store.USERS[user]["role"] == "auditor":
        return {"status": 200, "body": {"ids": sorted(store.INVOICES)}}
    owned = [key for key, invoice in store.INVOICES.items() if invoice["owner"] == user]
    return {"status": 200, "body": {"ids": owned}}


def get_invoice(request):
    user = request["user"]
    key = int(request["path_params"]["id"])
    invoice = store.INVOICES.get(key)
    if invoice is None:
        return {"status": 404, "body": {"error": "facture inconnue"}}
    if invoice["owner"] != user and store.USERS[user]["role"] != "auditor":
        return {"status": 403, "body": {"error": "accès refusé"}}
    return {"status": 200, "body": dict(invoice)}


def pay_invoice(request):
    return {"status": 202, "body": {"status": "paiement en cours"}}


def delete_invoice(request):
    return {"status": 204, "body": None}


# Source de vérité de la surface exposée : toute route passe par cette table.
ROUTES = [
    {"method": "GET", "path": "/health", "handler": "health", "public": True},
    {"method": "POST", "path": "/login", "handler": "login", "public": True},
    {"method": "GET", "path": "/invoices", "handler": "list_invoices", "public": False},
    {"method": "GET", "path": "/invoices/{id}", "handler": "get_invoice", "public": False},
    {"method": "POST", "path": "/invoices/{id}/pay", "handler": "pay_invoice", "public": False},
    {"method": "DELETE", "path": "/invoices/{id}", "handler": "delete_invoice", "public": False},
]

