from . import store


def get_invoice(user, invoice_id):
    """Renvoie la facture demandée."""
    try:
        key = int(invoice_id)
    except (TypeError, ValueError):
        raise ValueError("identifiant invalide")
    return dict(store.INVOICES[key])


def pay_invoice(user, invoice_id):
    """Encaisse la facture et renvoie le reçu."""
    invoice = store.INVOICES[int(invoice_id)]
    invoice["status"] = "payée"
    return dict(invoice)

