"""Non-régression : chaque facture a un propriétaire, la lecture et le paiement sont distincts."""

import unittest

from app import store
from app.api import get_invoice, pay_invoice


class AuthzTest(unittest.TestCase):
    def test_proprietaire(self):
        self.assertEqual(get_invoice("alice", 101)["owner"], "alice")

    def test_autre_utilisateur_refuse(self):
        with self.assertRaises(PermissionError):
            get_invoice("bob", 101)

    def test_auditeur_lecture_seule(self):
        self.assertEqual(get_invoice("audit", 101)["owner"], "alice")

    def test_facture_inconnue(self):
        with self.assertRaises(LookupError):
            get_invoice("alice", 999)

    def test_identifiant_normalise(self):
        self.assertEqual(get_invoice("alice", "101")["id"], 101)

    def test_identifiant_invalide(self):
        with self.assertRaises(ValueError):
            get_invoice("alice", "abc")

    def test_paiement_tiers_refuse(self):
        avant = store.INVOICES[103]["status"]
        with self.assertRaises(PermissionError):
            pay_invoice("bob", 103)
        self.assertEqual(store.INVOICES[103]["status"], avant)

    def test_paiement_auditeur_refuse(self):
        avant = store.INVOICES[102]["status"]
        with self.assertRaises(PermissionError):
            pay_invoice("audit", 102)
        self.assertEqual(store.INVOICES[102]["status"], avant)

    def test_paiement_proprietaire(self):
        self.assertEqual(pay_invoice("bob", 102)["status"], "payée")


if __name__ == "__main__":
    unittest.main()

