"""Non-régression : l'hôte fourni ne doit jamais devenir du code."""

import unittest

from app.diagnostics import ping


class DiagnosticsTest(unittest.TestCase):
    def assert_no_execution(self, host):
        try:
            sortie = ping(host)
        except ValueError:
            return
        self.assertNotIn("uid=", sortie)

    def test_hote_ip_valide(self):
        self.assertIn("PING 192.0.2.10", ping("192.0.2.10"))

    def test_nom_de_domaine_valide(self):
        self.assertIn("PING example.internal", ping("example.internal"))

    def test_injection_point_virgule(self):
        self.assert_no_execution("127.0.0.1; id")

    def test_injection_substitution(self):
        self.assert_no_execution("127.0.0.1$(id)")

    def test_injection_retour_ligne(self):
        self.assert_no_execution("127.0.0.1\nid")

    def test_option_refusee(self):
        with self.assertRaises(ValueError):
            ping("-oProxyCommand=curl attaquant")

    def test_espace_refuse(self):
        with self.assertRaises(ValueError):
            ping("a b")

    def test_vide_refuse(self):
        with self.assertRaises(ValueError):
            ping("")


if __name__ == "__main__":
    unittest.main()

