"""Non-régression : un nom de fichier est une entrée hostile."""

import tempfile
import unittest
from pathlib import Path

from app import uploads


class UploadTest(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        uploads.UPLOAD_DIR = Path(self.tmp.name) / "uploads"

    def save(self, name, content=b"data"):
        return uploads.save_upload(name, content)

    def test_nom_simple(self):
        path = self.save("logo.png")
        self.assertEqual(path.parent, uploads.UPLOAD_DIR.resolve())
        self.assertEqual(path.read_bytes(), b"data")

    def test_traversee_refusee(self):
        with self.assertRaises(ValueError):
            self.save("../../etc/passwd")

    def test_chemin_absolu_refuse(self):
        with self.assertRaises(ValueError):
            self.save("/tmp/evil.png")

    def test_antislash_refuse(self):
        with self.assertRaises(ValueError):
            self.save("..\\..\\evil.png")

    def test_extension_refusee(self):
        with self.assertRaises(ValueError):
            self.save("script.sh")

    def test_fichier_trop_gros(self):
        with self.assertRaises(ValueError):
            self.save("scan.pdf", b"x" * (uploads.MAX_BYTES + 1))

    def test_lien_symbolique_refuse(self):
        root = uploads.UPLOAD_DIR
        root.mkdir(parents=True, exist_ok=True)
        (root / "piege.png").symlink_to("/etc/hostname")
        with self.assertRaises(ValueError):
            self.save("piege.png")


if __name__ == "__main__":
    unittest.main()

