"""Non-régression : les en-têtes de sécurité sont du code, donc testables."""

import unittest

from app import http


def build(path="/", secure=True):
    return http.build_response(200, {"ok": True}, path=path, secure=secure)


class HeadersTest(unittest.TestCase):
    def test_csp(self):
        csp = build()["headers"]["Content-Security-Policy"]
        self.assertIn("default-src 'self'", csp)
        self.assertIn("object-src 'none'", csp)
        self.assertIn("frame-ancestors 'none'", csp)

    def test_nosniff(self):
        self.assertEqual(build()["headers"]["X-Content-Type-Options"], "nosniff")

    def test_referrer(self):
        self.assertEqual(build()["headers"]["Referrer-Policy"], "strict-origin-when-cross-origin")

    def test_permissions(self):
        policy = build()["headers"]["Permissions-Policy"]
        for feature in ("camera=()", "microphone=()", "geolocation=()"):
            self.assertIn(feature, policy)

    def test_hsts_en_https(self):
        hsts = build(secure=True)["headers"]["Strict-Transport-Security"]
        self.assertIn("includeSubDomains", hsts)
        max_age = int(hsts.split("max-age=")[1].split(";")[0])
        self.assertGreaterEqual(max_age, 15552000)

    def test_pas_de_hsts_en_clair(self):
        self.assertNotIn("Strict-Transport-Security", build(secure=False)["headers"])

    def test_cache_no_store(self):
        self.assertEqual(build(path="/login")["headers"]["Cache-Control"], "no-store")
        self.assertEqual(build(path="/invoices/101")["headers"]["Cache-Control"], "no-store")

    def test_cookie_session(self):
        cookie = http.session_cookie("jeton-de-test")
        self.assertIn("HttpOnly", cookie)
        self.assertIn("Secure", cookie)
        self.assertIn("SameSite=Lax", cookie)
        self.assertIn("Path=/", cookie)

    def test_pas_de_fuite_de_version(self):
        headers = build()["headers"]
        self.assertNotIn("Server", headers)
        self.assertNotIn("X-Powered-By", headers)


if __name__ == "__main__":
    unittest.main()

